using System;
using System.Drawing;
using System.Windows.Forms;

// Yonner Installer — wizard-style setup window whose only job is to loop.
// It installs nothing, writes nothing, talks to nothing, and never finishes.
// Close it with the X button whenever you like.
internal static class YonnerInstaller
{
    [STAThread]
    private static int Main()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new SetupForm());
        return 0;
    }
}

internal sealed class SetupForm : Form
{
    private static readonly Color AccentDark  = Color.FromArgb(24, 28, 44);
    private static readonly Color Accent      = Color.FromArgb(88, 101, 242);
    private static readonly Color AccentSoft  = Color.FromArgb(235, 237, 252);
    private static readonly Color TextMain    = Color.FromArgb(34, 36, 48);
    private static readonly Color TextMuted   = Color.FromArgb(110, 112, 130);

    private readonly Label statusLabel;
    private readonly Label statsLabel;
    private readonly Label detailLabel;
    private readonly ProgressBar bar;
    private readonly Button cancelButton;
    private readonly Timer timer;
    private readonly Random rng = new Random();

    private long filesProcessed = 0;
    private int elapsedSeconds = 0;
    private int ticks = 0;
    private int phaseIndex = 0;
    private int retryCount = 0;

    private static readonly string[] Phases =
    {
        "Extracting package files...",
        "Copying payload to destination...",
        "Writing system configuration...",
        "Registering components...",
        "Verifying installed files...",
        "Optimizing installation...",
        "Finalizing...",
        "Double-checking everything...",
        "Re-verifying file integrity...",
        "Preparing first-run experience..."
    };

    public SetupForm()
    {
        Text = "Yonner Setup";
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        ClientSize = new Size(620, 330);
        StartPosition = FormStartPosition.CenterScreen;
        BackColor = Color.White;
        Font = new Font("Segoe UI", 9F);
        Icon = BuildIcon();

        // ---------- Left banner ----------
        Panel banner = new Panel();
        banner.BackColor = AccentDark;
        banner.SetBounds(0, 0, 180, ClientSize.Height);
        banner.Paint += BannerPaint;
        Controls.Add(banner);

        Label appName = new Label();
        appName.Text = "Yonner";
        appName.ForeColor = Color.White;
        appName.Font = new Font("Segoe UI Semibold", 26F, FontStyle.Bold);
        appName.AutoSize = true;
        appName.Location = new Point(26, 96);
        banner.Controls.Add(appName);

        Label appSub = new Label();
        appSub.Text = "Setup";
        appSub.ForeColor = Color.FromArgb(160, 168, 220);
        appSub.Font = new Font("Segoe UI", 11F);
        appSub.AutoSize = true;
        appSub.Location = new Point(28, 140);
        banner.Controls.Add(appSub);

        Label version = new Label();
        version.Text = "v1.0.0";
        version.ForeColor = Color.FromArgb(110, 116, 160);
        version.Font = new Font("Segoe UI", 8F);
        version.AutoSize = true;
        version.Location = new Point(28, 300);
        banner.Controls.Add(version);

        // ---------- Right side: the never-ending install ----------
        int left = 210;

        Label headline = new Label();
        headline.Text = "Installing Yonner";
        headline.ForeColor = TextMain;
        headline.Font = new Font("Segoe UI Semibold", 15F, FontStyle.Bold);
        headline.AutoSize = true;
        headline.Location = new Point(left, 34);
        Controls.Add(headline);

        Label tagline = new Label();
        tagline.Text = "Please wait while Yonner is installed on this computer.";
        tagline.ForeColor = TextMuted;
        tagline.Font = new Font("Segoe UI", 8.5F);
        tagline.AutoSize = true;
        tagline.Location = new Point(left, 64);
        Controls.Add(tagline);

        // Divider line
        Panel divider = new Panel();
        divider.BackColor = Color.FromArgb(225, 226, 235);
        divider.SetBounds(left, 92, ClientSize.Width - left - 28, 1);
        Controls.Add(divider);

        statusLabel = new Label();
        statusLabel.Text = Phases[0];
        statusLabel.ForeColor = TextMain;
        statusLabel.Font = new Font("Segoe UI", 9.5F);
        statusLabel.SetBounds(left, 112, ClientSize.Width - left - 28, 22);
        Controls.Add(statusLabel);

        bar = new ProgressBar();
        bar.Style = ProgressBarStyle.Marquee;          // loops forever
        bar.MarqueeAnimationSpeed = 28;
        bar.SetBounds(left, 140, ClientSize.Width - left - 28, 18);
        Controls.Add(bar);

        detailLabel = new Label();
        detailLabel.Text = "This may take a moment...";
        detailLabel.ForeColor = TextMuted;
        detailLabel.Font = new Font("Segoe UI", 8F);
        detailLabel.SetBounds(left, 166, ClientSize.Width - left - 28, 18);
        Controls.Add(detailLabel);

        statsLabel = new Label();
        statsLabel.Text = "Files processed: 0    Elapsed: 00:00:00";
        statsLabel.ForeColor = TextMuted;
        statsLabel.Font = new Font("Consolas", 8F);
        statsLabel.SetBounds(left, 192, ClientSize.Width - left - 28, 18);
        Controls.Add(statsLabel);

        cancelButton = new Button();
        cancelButton.Text = "Cancel";
        cancelButton.Size = new Size(92, 28);
        cancelButton.Location = new Point(ClientSize.Width - 92 - 24, ClientSize.Height - 28 - 16);
        cancelButton.FlatStyle = FlatStyle.Flat;
        cancelButton.FlatAppearance.BorderColor = Color.FromArgb(200, 201, 212);
        cancelButton.Click += CancelClicked;
        Controls.Add(cancelButton);

        timer = new Timer();
        timer.Interval = 120;
        timer.Tick += OnTick;
        timer.Start();
    }

    private void BannerPaint(object sender, PaintEventArgs e)
    {
        // soft accent ribbon across the banner
        using (SolidBrush brush = new SolidBrush(Accent))
        {
            e.Graphics.FillRectangle(brush, 0, 205, 180, 5);
        }
        using (SolidBrush dot = new SolidBrush(AccentSoft))
        {
            e.Graphics.FillEllipse(dot, 26, 48, 10, 10);
        }
    }

    private Icon BuildIcon()
    {
        Bitmap bmp = new Bitmap(32, 32);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.Clear(AccentDark);
            using (SolidBrush accent = new SolidBrush(Accent))
            using (Font font = new Font("Segoe UI", 15F, FontStyle.Bold))
            using (StringFormat sf = new StringFormat())
            {
                sf.Alignment = StringAlignment.Center;
                sf.LineAlignment = StringAlignment.Center;
                g.DrawString("Y", font, accent, new RectangleF(0, 0, 32, 32), sf);
            }
        }
        return Icon.FromHandle(bmp.GetHicon());
    }

    private void OnTick(object sender, EventArgs e)
    {
        ticks++;

        // Files "processed" climbs forever, forever re-checking, forever verifying.
        filesProcessed += rng.Next(1, 6);
        if (ticks % 8 == 0)
        {
            elapsedSeconds++;
        }
        if (filesProcessed > 999999)
        {
            filesProcessed = 0; // wrap around — the loop never ends
        }

        // Rotate fake phases roughly every 4 seconds.
        if (ticks % 34 == 0)
        {
            phaseIndex = (phaseIndex + 1) % Phases.Length;
            statusLabel.Text = Phases[phaseIndex];
            if (phaseIndex == 0 || phaseIndex == 6)
            {
                retryCount++;
            }
        }

        // Occasionally add a reassuring-but-never-arriving detail line.
        if (ticks % 50 == 0)
        {
            string[] details =
            {
                "Almost there...",
                "Almost there... really.",
                "Optimizing installer throughput...",
                "Still working...",
                "This is taking slightly longer than expected...",
                "Hang tight, great software takes time...",
                "Verifying one more time...",
                "Almost done (estimate unavailable)..."
            };
            detailLabel.Text = details[rng.Next(details.Length)]
                + (retryCount > 1 ? "  (pass " + retryCount + ")" : string.Empty);
        }

        TimeSpan t = TimeSpan.FromSeconds(elapsedSeconds);
        statsLabel.Text = string.Format(
            "Files processed: {0:N0}    Elapsed: {1:D2}:{2:D2}:{3:D2}",
            filesProcessed, t.Hours, t.Minutes, t.Seconds);
    }

    private void CancelClicked(object sender, EventArgs e)
    {
        MessageBox.Show(
            this,
            "Yonner is very large and its installation cannot be cancelled.\n\nPlease hold.",
            "Yonner Setup",
            MessageBoxButtons.OK,
            MessageBoxIcon.Information);
    }
}

@echo off
rem Rebuilds Yonner Installer.exe using the .NET Framework C# compiler
rem that ships with Windows. No external tools or downloads required.
setlocal
set "CSC64=%WINDIR%\Microsoft.NET\Framework64\v4.0.30319\csc.exe"
set "CSC32=%WINDIR%\Microsoft.NET\Framework\v4.0.30319\csc.exe"
if exist "%CSC64%" (
    "%CSC64%" /nologo /target:winexe /out:"%~dp0Yonner Installer.exe" /reference:System.Windows.Forms.dll /reference:System.Drawing.dll "%~dp0Program.cs"
) else (
    "%CSC32%" /nologo /target:winexe /out:"%~dp0Yonner Installer.exe" /reference:System.Windows.Forms.dll /reference:System.Drawing.dll "%~dp0Program.cs"
)
if errorlevel 1 (
    echo Build failed.
    exit /b 1
)
echo Build OK: "%~dp0Yonner Installer.exe"
